def build_messages(query, tool_calls_results):
    messages = [{"role": "user", "content": query}]
    for tool_use_id, name, input_dict, result in tool_calls_results:
        messages.append({
            "role": "assistant",
            "content": [{"type": "tool_use", "id": tool_use_id, "name": name, "input": input_dict}]
        })
        messages.append({
            "role": "user",
            "content": [{"type": "tool_result", "tool_use_id": tool_use_id, "content": result}]
        })
    return messages

